@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

/*
 * Lumen Dark — built around Better Design's Depth & Surfaces principle.
 *
 * Core ideas applied:
 * - Light source from above (inset top-edge highlights simulate light hitting surfaces)
 * - Three-tier shadow scale (s/m/l) with 3 layers each: inset highlight + contact + ambient
 * - Elevation via BOTH background shift and shadow layering (higher surfaces are lighter)
 * - Shadows over borders on interactive surfaces
 * - Color transitions paired with shadow transitions on hover (depth principle §"Combining Color and Shadows")
 */

:root {
  /* ─── Surfaces (elevation = lighter bg) ─── */
  --background: oklch(0.14 0 0);          /* Deepest plane */
  --foreground: oklch(0.97 0.01 85);      /* Warm white */

  --card: oklch(0.17 0 0);                 /* Raised surface */
  --card-foreground: oklch(0.97 0.01 85);

  --popover: oklch(0.19 0 0);              /* Floating surface */
  --popover-foreground: oklch(0.97 0.01 85);

  /* ─── Primary: warm amber (named "lumen" for the warm light metaphor) ─── */
  --primary: oklch(0.78 0.14 85);          /* Amber */
  --primary-foreground: oklch(0.16 0.02 85);

  --secondary: oklch(0.22 0 0);
  --secondary-foreground: oklch(0.85 0 0);

  --muted: oklch(0.2 0 0);
  --muted-foreground: oklch(0.6 0 0);

  --accent: oklch(0.25 0.015 85);          /* Warm-tinted accent bg */
  --accent-foreground: oklch(0.97 0.01 85);

  --destructive: oklch(0.64 0.22 25);
  --destructive-foreground: oklch(0.97 0 0);

  --border: oklch(1 0 0 / 0.08);           /* Subtle white 8% */
  --input: oklch(1 0 0 / 0.06);
  --ring: oklch(0.78 0.14 85);             /* Amber ring matches primary */
  --radius: 0.5rem;

  /*
   * ─── Shadow scale (5 tiers following Better Design's depth principle) ───
   *
   * Each tier stacks three layers:
   *   1. Inset highlight  — light from above hitting the top edge
   *   2. Contact shadow   — sharp, close, where the element "touches" the surface
   *   3. Ambient shadow   — soft, diffused, environmental
   *
   * The principle doc prescribes highlight opacities of 30/50/70% and contact/ambient
   * at 30%/15% black — those values target LIGHT themes. Dark themes need lower
   * highlights (bright whites read as gaudy on dark bg) and deeper shadows (higher
   * opacity to register against dark canvas). The progression below keeps the 1:2
   * offset/blur ratio between contact and ambient layers per the spec.
   *
   * Tier usage:
   *   xs  → dots, chips, status pills (barely-there lift)
   *   sm  → buttons, small cards (resting elevation)
   *   md  → hover state of sm, interactive cards, elevated buttons
   *   lg  → dropdowns, popovers, tooltips (floating)
   *   xl  → dialogs, sheets, modals (maximum elevation)
   */
  --shadow-xs:
    inset 0 1px 0 rgba(255, 255, 255, 0.03),
    0 1px 1px rgba(0, 0, 0, 0.35),
    0 1px 2px rgba(0, 0, 0, 0.15);

  --shadow-sm:
    inset 0 1px 0 rgba(255, 255, 255, 0.05),
    0 1px 2px rgba(0, 0, 0, 0.4),
    0 2px 4px rgba(0, 0, 0, 0.2);

  --shadow-md:
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    0 2px 4px rgba(0, 0, 0, 0.5),
    0 4px 8px rgba(0, 0, 0, 0.25);

  --shadow-lg:
    inset 0 1px 0 rgba(255, 255, 255, 0.12),
    0 4px 8px rgba(0, 0, 0, 0.6),
    0 8px 16px rgba(0, 0, 0, 0.3);

  --shadow-xl:
    inset 0 1px 0 rgba(255, 255, 255, 0.18),
    0 8px 16px rgba(0, 0, 0, 0.7),
    0 16px 32px rgba(0, 0, 0, 0.35);

  /* Inset/pressed — inputs sit BELOW the surface plane (light falls into the recess) */
  --shadow-inset:
    inset 0 1px 2px rgba(0, 0, 0, 0.35),
    inset 0 -1px 0 rgba(255, 255, 255, 0.03);

  /* Amber-glow variant for primary buttons — shadow-md + warm color bloom layer */
  --shadow-primary:
    inset 0 1px 0 rgba(255, 255, 255, 0.25),
    0 0 0 1px rgba(255, 200, 100, 0.2),
    0 2px 4px rgba(0, 0, 0, 0.5),
    0 4px 12px rgba(240, 170, 60, 0.18);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --radius-sm: calc(var(--radius) - 2px);
  --radius-md: var(--radius);
  --radius-lg: calc(var(--radius) + 2px);
  --radius-xl: calc(var(--radius) + 6px);

  --shadow-s: var(--shadow-s);
  --shadow-m: var(--shadow-m);
  --shadow-l: var(--shadow-l);
  --shadow-inset: var(--shadow-inset);
  --shadow-button: var(--shadow-button);
  --shadow-button-hover: var(--shadow-button-hover);
  --shadow-primary: var(--shadow-primary);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground antialiased;
  }
}
